import * as T from 'three';import{VoxelAssetFactory}from'./VoxelAssetFactory.js';export const PETS=Array.from({length:40},(_,i)=>({id:i,name:['Cachorrinho','Dragão','Gatinho','Dinossauro','Coelho','Raposa','Unicórnio','Robô'][i%8]+(i>=8?' '+['Estelar','Gelado','Doce','Cristal'][Math.floor(i/8)-1]:''),power:1+Math.floor(i/5),icon:['🐶','🐉','🐱','🦕','🐰','🦊','🦄','🤖'][i%8]}));export const PetFactory={create(id){const g=VoxelAssetFactory.pet(id,id>=16);if(id>=16)g.traverse(o=>{if(o.isMesh){o.material=o.material.clone();o.material.emissive=new T.Color(id>=32?0xffd663:0x7c48bf);o.material.emissiveIntensity=.18}});return g}};
